import type { Area } from "../area";

/**
 * THE PRIVACY NOTICE AND THE TERMS IN RUSSIAN AND UKRAINIAN.
 *
 * Two legal texts, which is why this area is written differently from the
 * rest. Every sentence is one row, kept whole, so a lawyer comparing the two
 * languages compares a sentence with a sentence. The wording is plain rather
 * than legalese, which is what the English is, and it uses the terms the GDPR
 * itself uses in each language (контролёр / контролер, обработка / обробка,
 * Европейская экономическая зона / Європейська економічна зона).
 *
 * THE ENGLISH PREVAILS, AND BOTH PAGES SAY SO FIRST (`LEGAL_NOTICE` in
 * lib/copy/publicLocale.ts). These rows were written with AI and have been
 * read by neither a native speaker nor a lawyer. The facts a page generates
 * (the operator, the recipients, the supervisory authority's address) are
 * never written here: they are rendered from the same data in every language.
 *
 * `{name}` slots are the page's own values and elements; `**bold**` and
 * `` `code` `` are drawn by components/Rich.tsx. No Estonian (ADR-005).
 */
const LINES: readonly (readonly [en: string, ru: string, uk: string])[] = [
  // THE SHELL OF EVERY PUBLIC POLICY PAGE.
  ["Last updated", "Обновлено", "Оновлено"],
  ["Privacy", "Конфиденциальность", "Конфіденційність"],
  ["Terms", "Условия", "Умови"],
  ["Funding", "Финансирование", "Фінансування"],
  ["Trust", "Доверие", "Довіра"],
  ["Accessibility", "Доступность", "Доступність"],
  ["The state examination", "Государственный экзамен", "Державний іспит"],
  ["Language", "Язык", "Мова"],
  ["January@date", "января", "січня"],
  ["February@date", "февраля", "лютого"],
  ["March@date", "марта", "березня"],
  ["April@date", "апреля", "квітня"],
  ["May@date", "мая", "травня"],
  ["June@date", "июня", "червня"],
  ["July@date", "июля", "липня"],
  ["August@date", "августа", "серпня"],
  ["September@date", "сентября", "вересня"],
  ["October@date", "октября", "жовтня"],
  ["November@date", "ноября", "листопада"],
  ["December@date", "декабря", "грудня"],
  ["registry code {code}", "регистрационный код {code}", "реєстраційний код {code}"],
  ["VAT number {vat}", "номер плательщика НДС {vat}", "номер платника ПДВ {vat}"],

  // PRIVACY.
  ["Kodukeel is an app for learning Estonian. This page tells you exactly what it keeps about you, why it’s allowed to, who else gets to see it, and how to make it go away.",
    "Kodukeel помогает учить эстонский язык. На этой странице точно сказано, что приложение о вас хранит, на каком основании, кто ещё это видит и как всё это удалить.",
    "Kodukeel допомагає вчити естонську мову. На цій сторінці точно сказано, що застосунок про вас зберігає, на якій підставі, хто ще це бачить і як усе це видалити."],
  ["Who holds this", "Кто отвечает за данные", "Хто відповідає за дані"],
  ["The controller of your data, meaning the one who answers for it, is **{name}**{registry}{vat}, at {address}. Write to {email} about anything on this page, including any of the requests below.",
    "Контролёр ваших данных, то есть тот, кто за них отвечает: **{name}**{registry}{vat}, адрес: {address}. По любому вопросу с этой страницы, в том числе с любым из запросов ниже, пишите на {email}.",
    "Контролер ваших даних (володілець даних), тобто той, хто за них відповідає: **{name}**{registry}{vat}, адреса: {address}. З будь-якого питання з цієї сторінки, зокрема з будь-яким із запитів нижче, пишіть на {email}."],
  ["There’s no data protection officer. This is a small installation, and the law only requires one of a public body or of a business built on monitoring people at scale, which this isn’t. The address above reaches a real person.",
    "Ответственного за защиту данных нет. Это небольшая установка, а назначить такого человека закон требует только от государственного органа или от бизнеса, построенного на масштабном наблюдении за людьми, и это не тот случай. Письмо на адрес выше читает живой человек.",
    "Відповідальної особи з питань захисту даних немає. Це невелика інсталяція, а призначити таку особу закон вимагає лише від державного органу або від бізнесу, побудованого на масштабному стеженні за людьми, і це не той випадок. Лист на адресу вище читає жива людина."],
  ["**Whoever runs this installation has not filled their name in.** Kodukeel is software anyone can install, not a service with one address, so whoever runs this copy, a person or a school, is the one who answers for your data. They’re supposed to be named here and aren’t, which you can complain about to the authority named further down. Ask whoever gave you the link. If you’re running this yourself, set `OPERATOR_NAME`, `OPERATOR_ADDRESS` and `OPERATOR_EMAIL` and this paragraph will show your details instead.",
    "**Тот, кто управляет этой установкой, не указал своё имя.** Kodukeel может установить кто угодно, это программа, а не сервис с одним адресом, поэтому за ваши данные отвечает тот, кто управляет этой копией: человек или школа. Его имя должно стоять здесь, но его нет, и на это можно пожаловаться в надзорный орган, указанный ниже. Спросите того, кто дал вам ссылку. Если вы запустили приложение сами, задайте `OPERATOR_NAME`, `OPERATOR_ADDRESS` и `OPERATOR_EMAIL`, и вместо этого абзаца здесь появятся ваши данные.",
    "**Той, хто керує цією інсталяцією, не вказав свого імені.** Kodukeel може встановити будь-хто, це програма, а не сервіс з однією адресою, тож за ваші дані відповідає той, хто керує цією копією: людина або школа. Його ім'я має стояти тут, але його немає, і на це можна поскаржитися до наглядового органу, вказаного нижче. Запитайте того, хто дав вам посилання. Якщо ви запустили застосунок самі, задайте `OPERATOR_NAME`, `OPERATOR_ADDRESS` і `OPERATOR_EMAIL`, і замість цього абзацу тут з'являться ваші дані."],
  ["What we keep, and why we’re allowed to", "Что мы храним и на каком основании", "Що ми зберігаємо і на якій підставі"],
  ["**Your identity.** Signing in with Google gives us your email address and a user id, held by Supabase Auth. We never see your Google password, and we don’t ask for anything else in your Google account. Without this we couldn’t show you your own deck instead of somebody else’s, so we keep it to provide the service you asked for.",
    "**Кто вы.** Вход через Google даёт нам ваш адрес электронной почты и идентификатор пользователя, которые хранятся в Supabase Auth. Ваш пароль от Google мы не видим никогда и больше ничего из вашего аккаунта Google не запрашиваем. Без этого мы не смогли бы показать вам вашу колоду, а не чужую, поэтому храним это, чтобы предоставлять услугу, о которой вы попросили.",
    "**Хто ви.** Вхід через Google дає нам вашу адресу електронної пошти та ідентифікатор користувача, які зберігаються в Supabase Auth. Вашого пароля від Google ми не бачимо ніколи і більше нічого з вашого облікового запису Google не запитуємо. Без цього ми не змогли б показати вам вашу колоду, а не чужу, тож зберігаємо це, щоб надавати послугу, про яку ви попросили."],
  ["**Your learning.** The cards in your deck, every review you have ever done (the grade, the moment, and how long you took), your tasks, your starred words, the words you have put aside as too complicated, your badges and your settings. The review log is what makes the scheduling work. It’s the app’s memory of how well you know each word, and an app that forgot it wouldn’t be the app you signed up for.",
    "**Ваша учёба.** Карточки в вашей колоде, каждое повторение, которое вы когда-либо делали (оценка, момент и сколько времени оно заняло), ваши задания, отмеченные звёздочкой слова, слова, отложенные как слишком сложные, ваши значки и настройки. На журнале повторений держится всё расписание. Это память приложения о том, насколько хорошо вы знаете каждое слово, и приложение, которое бы её забыло, было бы уже не тем, в котором вы зарегистрировались.",
    "**Ваше навчання.** Картки у вашій колоді, кожне повторення, яке ви будь-коли робили (оцінка, момент і скільки часу воно забрало), ваші завдання, слова, позначені зірочкою, слова, відкладені як надто складні, ваші значки та налаштування. На журналі повторень тримається весь розклад. Це пам'ять застосунку про те, наскільки добре ви знаєте кожне слово, і застосунок, який би її забув, був би вже не тим, у якому ви зареєструвалися."],
  ["**What we have sent you.** If this installation sends email, we keep a line for each message: which kind it was and when it went, so that the next one is not a repeat and so that there is a cap on how often you hear from us. We do **not** keep the message itself, and there is no tracking pixel in any of them, so nothing anywhere records whether you opened one. Every message carries a link that switches its kind off without signing in, and Settings has the same switches. The messages you cannot switch off are the ones you asked for, like a sign-in link.",
    "**Что мы вам отправили.** Если эта установка рассылает письма, мы храним по строке на каждое: какого оно было вида и когда ушло, чтобы следующее не повторяло его и чтобы было ограничение на то, как часто вы от нас что-то получаете. Само письмо мы **не** храним, и ни в одном нет пикселя отслеживания, так что нигде не записывается, открыли ли вы его. В каждом письме есть ссылка, которая отключает письма этого вида без входа в аккаунт, и те же переключатели есть в настройках. Отключить нельзя только письма, о которых вы попросили сами, например ссылку для входа.",
    "**Що ми вам надіслали.** Якщо ця інсталяція надсилає листи, ми зберігаємо по рядку на кожен: якого він був виду і коли пішов, щоб наступний не повторював його і щоб було обмеження на те, як часто ви щось від нас отримуєте. Самого листа ми **не** зберігаємо, і в жодному немає пікселя відстеження, тож ніде не записується, чи ви його відкрили. У кожному листі є посилання, яке вимикає листи цього виду без входу в обліковий запис, і ті самі перемикачі є в налаштуваннях. Вимкнути не можна лише листи, які ви попросили самі, наприклад посилання для входу."],
  ["**And one of them is about other people.** Whoever runs a class or a workplace group can be sent a weekly note about it. That note carries how many people practiced and how many answers they gave between them, and never a name, a figure about one person, or anybody’s mistakes. Those are on the board inside the app, where everyone who joined was told they would be. It is switched off from the group’s own page.",
    "**И одно из них касается других людей.** Тот, кто ведёт группу или рабочую группу, может получать о ней еженедельную записку. В ней сказано, сколько людей занималось и сколько ответов они дали вместе, но никогда нет имени, цифры об одном человеке или чьих-то ошибок. Всё это есть на доске внутри приложения, и каждого, кто вступал в группу, об этом предупредили. Отключается записка на странице самой группы.",
    "**І один із них стосується інших людей.** Той, хто веде групу або робочу групу, може отримувати про неї щотижневу записку. У ній сказано, скільки людей займалося і скільки відповідей вони дали разом, але ніколи немає імені, цифри про одну людину чи чиїхось помилок. Усе це є на дошці всередині застосунку, і кожного, хто вступав до групи, про це попередили. Вимикається записка на сторінці самої групи."],
  ["**Your level checks.** Each sitting is kept: the levels it measured, how many questions it came from, and the rating you gave your own speaking. Nothing you record is uploaded, and no audio is stored anywhere.",
    "**Ваши проверки уровня.** Каждая попытка сохраняется: какие уровни она показала, из скольких вопросов, и как вы сами оценили своё говорение. Ничего из того, что вы записываете, не загружается, и аудио нигде не хранится.",
    "**Ваші перевірки рівня.** Кожна спроба зберігається: які рівні вона показала, зі скількох запитань, і як ви самі оцінили своє говоріння. Нічого з того, що ви записуєте, не завантажується, і аудіо ніде не зберігається."],
  ["**Your mock exams.** A sat paper is kept whole: the level, your score, and the marked paper itself, question by question, with what was expected and what you gave. That includes **the composition you wrote**, kept in your own words, because a piece of writing is only worth going back to if it is the piece you actually wrote. It is the longest thing you write anywhere in this app, which is why it has a line of its own here. A paper you abandon is never saved to your account. You mark the spoken part yourself, and nothing you record leaves your device.",
    "**Ваши пробные экзамены.** Сданный вариант сохраняется целиком: уровень, ваш результат и сама проверенная работа, вопрос за вопросом, с тем, что ожидалось, и тем, что ответили вы. Сюда входит и **ваше сочинение**, сохранённое вашими словами, потому что к тексту стоит возвращаться, только если это именно тот текст, который вы написали. Это самое длинное, что вы пишете в этом приложении, поэтому о нём здесь отдельная строка. Брошенный вариант в ваш аккаунт не сохраняется никогда. Устную часть вы оцениваете сами, и ничего из записанного не покидает ваше устройство.",
    "**Ваші пробні іспити.** Складений варіант зберігається цілком: рівень, ваш результат і сама перевірена робота, запитання за запитанням, з тим, що очікувалося, і тим, що відповіли ви. Сюди входить і **ваш твір**, збережений вашими словами, бо до тексту варто повертатися, лише якщо це саме той текст, який ви написали. Це найдовше, що ви пишете в цьому застосунку, тому про нього тут окремий рядок. Покинутий варіант до вашого облікового запису не зберігається ніколи. Усну частину ви оцінюєте самі, і нічого із записаного не залишає ваш пристрій."],
  ["**Your conversations in Situations.** Each one you finish is kept whole: who was behind the desk, what was on the role card, what went wrong on purpose, every turn, and where each of the other side's lines came from. **Nothing in a transcript is about you.** You play a patient, a tenant, a customer, with a card of invented facts and a document number that is fiction, and you are never asked for your own. The words a conversation needed and you did not have are kept as a list, so they can be handed back. A conversation you walk out of is kept as one you walked out of; one you abandon by closing the tab is kept on your device only, and goes nowhere until you finish it.",
    "**Ваши разговоры в «Ситуациях».** Каждый законченный разговор сохраняется целиком: кто был по ту сторону стойки, что было в карточке роли, что пошло не так нарочно, каждая реплика и откуда взялась каждая реплика собеседника. **Ничто в записи разговора не касается вас лично.** Вы играете пациента, жильца, покупателя по карточке с выдуманными фактами и вымышленным номером документа, и ваш собственный у вас никогда не спрашивают. Слова, которые понадобились в разговоре и которых у вас не было, сохраняются списком, чтобы их можно было вам вернуть. Разговор, из которого вы ушли, сохраняется как разговор, из которого вы ушли; разговор, брошенный закрытием вкладки, остаётся только на вашем устройстве и никуда не уходит, пока вы его не закончите.",
    "**Ваші розмови в «Ситуаціях».** Кожна закінчена розмова зберігається цілком: хто був по той бік стійки, що було в картці ролі, що пішло не так навмисно, кожна репліка і звідки взялася кожна репліка співрозмовника. **Ніщо в записі розмови не стосується вас особисто.** Ви граєте пацієнта, мешканця, покупця за карткою з вигаданими фактами й вигаданим номером документа, і вашого власного у вас ніколи не питають. Слова, які знадобилися в розмові і яких у вас не було, зберігаються списком, щоб їх можна було вам повернути. Розмова, з якої ви пішли, зберігається як розмова, з якої ви пішли; розмова, покинута закриттям вкладки, лишається тільки на вашому пристрої й нікуди не йде, доки ви її не закінчите."],
  ["**What you said happened out there.** Today asks each morning whether you spoke any Estonian to somebody yesterday. Where the answer is no, that is the whole of it; where it is yes, it asks how it went, in one of three words: they understood me, I got stuck partway, they switched to English. That word and the day are kept, and nothing else: not where you were, not who you spoke to, not what was said. The errand it offers on a day with none is not stored at all.",
    "**Что, по вашим словам, было в жизни.** Каждое утро экран «Сегодня» спрашивает, говорили ли вы вчера с кем-нибудь по-эстонски. Если нет, на этом всё; если да, он спрашивает, как всё прошло, одним из трёх вариантов: меня поняли, я застрял на полпути, со мной перешли на английский. Сохраняются этот ответ и день, и больше ничего: ни где вы были, ни с кем говорили, ни что было сказано. Задание, которое он предлагает в день без разговоров, не сохраняется вовсе.",
    "**Що, за вашими словами, було в житті.** Щоранку екран «Сьогодні» питає, чи говорили ви вчора з кимось естонською. Якщо ні, на цьому все; якщо так, він питає, як усе пройшло, одним із трьох варіантів: мене зрозуміли, я застряг на півдорозі, зі мною перейшли на англійську. Зберігаються ця відповідь і день, і більше нічого: ні де ви були, ні з ким говорили, ні що було сказано. Завдання, яке він пропонує в день без розмов, не зберігається зовсім."],
  ["**Your class, if you are in one.** Joining with a code stores which class you joined, when, and the name you chose to be known by in it, which is the one place you can be under a name of your own choosing rather than your account. If you run a class, its name and its join code are stored against you. What a teacher sees of a student is only ever effort, never contents: reviews this week, a streak, words known, when they were last here, which grammar the class as a whole is weakest at, and which grammar that student personally is weakest at, as a percentage rolled up over their own reviews. Never a deck, a search or a specific answer. Leaving a class removes your membership of it, and deleting your account removes every class you are in and every class you run.",
    "**Ваша группа, если вы в ней состоите.** При вступлении по коду сохраняется, в какую группу вы вступили, когда и под каким именем вы решили в ней значиться; это единственное место, где вы можете быть под именем по своему выбору, а не под именем аккаунта. Если вы ведёте группу, её название и код для вступления хранятся за вами. Учитель видит у ученика только усилия, никогда не содержимое: повторения за неделю, серию дней, известные слова, когда ученик заходил последний раз, в какой грамматике слабее всего группа в целом и в какой лично этот ученик, в виде процента, сведённого по его собственным повторениям. Никогда не колоду, не поиск и не конкретный ответ. Выход из группы удаляет ваше членство в ней, а удаление аккаунта удаляет все группы, в которых вы состоите, и все, которые вы ведёте.",
    "**Ваша група, якщо ви в ній.** Під час вступу за кодом зберігається, до якої групи ви вступили, коли і під яким ім'ям ви вирішили в ній бути; це єдине місце, де ви можете бути під ім'ям на свій вибір, а не під ім'ям облікового запису. Якщо ви ведете групу, її назва і код для вступу зберігаються за вами. Учитель бачить в учня лише зусилля, ніколи не вміст: повторення за тиждень, серію днів, відомі слова, коли учень заходив востаннє, у якій граматиці найслабша група загалом і в якій особисто цей учень, у вигляді відсотка, зведеного за його власними повтореннями. Ніколи не колоду, не пошук і не конкретну відповідь. Вихід із групи видаляє ваше членство в ній, а видалення облікового запису видаляє всі групи, у яких ви є, і всі, які ви ведете."],
  ["**Your workplace group, if an employer sponsors you.** A group set up by an employer is the same membership row, and it shows them less than a teacher sees rather than more. They get your name, whether you have been reviewing and when you last did, and one of four bands for the examination the group works toward. Not a percentage, not which grammar you personally find hard, and never a deck, a search or an answer. The band is withheld entirely until there is enough history behind it to mean something. Leaving stops all of it at once and takes nothing from your own deck.",
    "**Ваша рабочая группа, если вас спонсирует работодатель.** Группа, созданная работодателем, хранится той же строкой членства и показывает ему меньше, чем видит учитель, а не больше. Он видит ваше имя, повторяли ли вы и когда последний раз, и одну из четырёх ступеней готовности к экзамену, к которому идёт группа. Не процент, не то, какая грамматика трудна лично вам, и никогда не колоду, не поиск и не ответ. Ступень не показывается вовсе, пока за ней нет достаточной истории, чтобы она что-то значила. Выход из группы сразу прекращает всё это и ничего не забирает из вашей колоды.",
    "**Ваша робоча група, якщо вас спонсорує роботодавець.** Група, створена роботодавцем, зберігається тим самим рядком членства і показує йому менше, ніж бачить учитель, а не більше. Він бачить ваше ім'я, чи ви повторювали і коли востаннє, та один із чотирьох ступенів готовності до іспиту, до якого йде група. Не відсоток, не те, яка граматика складна особисто вам, і ніколи не колоду, не пошук і не відповідь. Ступінь не показується зовсім, доки за ним немає достатньої історії, щоб він щось означав. Вихід із групи одразу припиняє все це й нічого не забирає з вашої колоди."],
  ["**Your conversations with Anu.** Messages you send the tutor and its replies are kept for a day, so the conversation survives a page reload, and no longer: the next time you speak to her, anything older than 24 hours is deleted and she starts fresh.",
    "**Ваши разговоры с Ану.** Сообщения, которые вы отправляете Ану, и её ответы хранятся сутки, чтобы разговор пережил перезагрузку страницы, и не дольше: в следующий раз, когда вы к ней обратитесь, всё старше 24 часов удаляется, и она начинает с чистого листа.",
    "**Ваші розмови з Ану.** Повідомлення, які ви надсилаєте Ану, та її відповіді зберігаються добу, щоб розмова пережила перезавантаження сторінки, і не довше: наступного разу, коли ви до неї звернетеся, усе старше за 24 години видаляється, і вона починає з чистого аркуша."],
  ["**Pages you photograph.** When you scan a page, what is kept is the word list you confirmed: the Estonian, the English, and which dictionary entry each word matched. **The photograph itself is never stored.** It is read once, on the way through, and dropped. It is not written to a database, not put in file storage, and not written to a log. A picture of your homework has your name at the top of it.",
    "**Страницы, которые вы фотографируете.** Когда вы сканируете страницу, сохраняется подтверждённый вами список слов: эстонское слово, английское и с какой словарной статьёй совпало каждое. **Сама фотография не хранится никогда.** Её читают один раз, по пути, и выбрасывают. Она не записывается ни в базу данных, ни в файловое хранилище, ни в журнал. На фотографии вашего домашнего задания сверху стоит ваше имя.",
    "**Сторінки, які ви фотографуєте.** Коли ви скануєте сторінку, зберігається підтверджений вами список слів: естонське слово, англійське і з якою словниковою статтею збіглося кожне. **Сама фотографія не зберігається ніколи.** Її читають один раз, дорогою, і викидають. Вона не записується ні в базу даних, ні у файлове сховище, ні в журнал. На фотографії вашого домашнього завдання вгорі стоїть ваше ім'я."],
  ["**What the tutor cost.** For every request to the AI, we keep a record: which model answered, roughly how much text went in and out, and what it is estimated to have cost. The tutor runs on somebody’s paid key and anyone can sign up, so a daily allowance per person is the only thing standing between an open door and an endless bill. We keep this because there’s a legitimate interest in a free service surviving the week, and there’s no way to run that cap without counting.",
    "**Сколько стоил репетитор.** О каждом запросе к ИИ мы храним запись: какая модель ответила, примерно сколько текста ушло туда и обратно и во сколько это, по оценке, обошлось. Репетитор работает на чьём-то платном ключе, а зарегистрироваться может любой, поэтому дневной лимит на человека остаётся единственным, что стоит между открытой дверью и бесконечным счётом. Мы храним это, потому что есть законный интерес в том, чтобы бесплатный сервис дожил до конца недели, а соблюдать лимит, ничего не считая, невозможно.",
    "**Скільки коштувала репетиторка.** Про кожен запит до ШІ ми зберігаємо запис: яка модель відповіла, приблизно скільки тексту пішло туди й назад і скільки це, за оцінкою, коштувало. Репетитор працює на чиємусь платному ключі, а зареєструватися може будь-хто, тож денний ліміт на людину лишається єдиним, що стоїть між відчиненими дверима й нескінченним рахунком. Ми зберігаємо це, бо є законний інтерес у тому, щоб безплатний сервіс дожив до кінця тижня, а дотримуватися ліміту, нічого не рахуючи, неможливо."],
  ["**What you report as wrong.** Anywhere the app cannot help you there is a button to tell us so. What you send is kept: what kind of problem it was, the screen you were on, what the app had just said to you, the correction you proposed and anything you wrote. Whoever runs this installation reads it, so treat that box as something another person will see, and please don’t put anything private in it. It is kept because a shared dictionary that nobody can correct goes wrong quietly, and because you asked us to look at it. Your own reports and what happened to each are on the **Suggestions** page, they are in the export, and they are deleted with your account.",
    "**О чём вы сообщаете как об ошибке.** Везде, где приложение не может вам помочь, есть кнопка, чтобы сказать нам об этом. Отправленное сохраняется: что это была за проблема, на каком вы были экране, что приложение вам только что сказало, какое исправление вы предложили и всё, что вы написали. Это читает тот, кто управляет этой установкой, поэтому относитесь к этому полю как к тому, что увидит другой человек, и, пожалуйста, не пишите туда ничего личного. Это хранится, потому что общий словарь, который никто не может исправить, тихо портится, и потому что вы сами попросили нас посмотреть. Ваши сообщения и то, что с каждым из них стало, есть на странице **Предложения**, они входят в экспорт и удаляются вместе с вашим аккаунтом.",
    "**Про що ви повідомляєте як про помилку.** Скрізь, де застосунок не може вам допомогти, є кнопка, щоб сказати нам про це. Надіслане зберігається: що це була за проблема, на якому ви були екрані, що застосунок вам щойно сказав, яке виправлення ви запропонували і все, що ви написали. Це читає той, хто керує цією інсталяцією, тож ставтеся до цього поля як до того, що побачить інша людина, і, будь ласка, не пишіть туди нічого особистого. Це зберігається, бо спільний словник, який ніхто не може виправити, тихо псується, і бо ви самі попросили нас подивитися. Ваші повідомлення і те, що з кожним із них сталося, є на сторінці **Пропозиції**, вони входять до експорту й видаляються разом із вашим обліковим записом."],
  ["**Errors.** When something breaks, we log the error message and where it happened, along with your account id, never your email. Anything that looks like a password or key is stripped out before it is written down. Same reason: an app nobody can debug is an app that stays broken.",
    "**Ошибки.** Когда что-то ломается, мы записываем сообщение об ошибке и где она случилась, вместе с идентификатором вашего аккаунта, но никогда не с вашей почтой. Всё, что похоже на пароль или ключ, вычищается до записи. Причина та же: приложение, которое никто не может отладить, так и остаётся сломанным.",
    "**Помилки.** Коли щось ламається, ми записуємо повідомлення про помилку і де вона сталася, разом з ідентифікатором вашого облікового запису, але ніколи з вашою поштою. Усе, що схоже на пароль чи ключ, вичищається до запису. Причина та сама: застосунок, який ніхто не може налагодити, так і лишається зламаним."],
  ["**What is not stored.** No analytics, no advertising identifiers, no third-party trackers, no profiling, and no cookie that is not needed to keep you signed in.",
    "**Что не хранится.** Никакой аналитики, никаких рекламных идентификаторов, никаких сторонних трекеров, никакого профилирования и ни одного файла cookie, кроме того, что нужен, чтобы вы оставались в аккаунте.",
    "**Що не зберігається.** Жодної аналітики, жодних рекламних ідентифікаторів, жодних сторонніх трекерів, жодного профілювання і жодного файлу cookie, крім того, що потрібен, щоб ви лишалися в обліковому записі."],
  ["**How we tell whether the app works.** We count, from the review log described above, how many people come back after a day, a week and a month. It is worked out from what is already there rather than collected separately, which is why there is still no tracker on this site. Only totals ever leave that page: no name, no address, no word you looked up. A group of fewer than five people is reported as a size with no percentage, because “one of two people came back” is a fact about a person rather than a statistic.",
    "**Как мы понимаем, работает ли приложение.** По журналу повторений, описанному выше, мы считаем, сколько людей возвращается через день, неделю и месяц. Это вычисляется из того, что уже есть, а не собирается отдельно, поэтому на сайте до сих пор нет трекера. С той страницы уходят только итоги: ни имени, ни адреса, ни слова, которое вы искали. Группа меньше пяти человек показывается только размером, без процента, потому что «вернулся один из двоих» говорит о человеке, а не о статистике.",
    "**Як ми розуміємо, чи працює застосунок.** За журналом повторень, описаним вище, ми рахуємо, скільки людей повертається через день, тиждень і місяць. Це обчислюється з того, що вже є, а не збирається окремо, тому на сайті досі немає трекера. З тієї сторінки йдуть лише підсумки: ні імені, ні адреси, ні слова, яке ви шукали. Група менше ніж з п'яти людей показується лише розміром, без відсотка, бо «повернувся один із двох» говорить про людину, а не про статистику."],
  ["**What learners of Estonian get wrong, counted.** From the same review log, this installation can produce a table of how often each grammatical case, each stem change and each word is answered correctly, added up across everybody. It is worked out from what is already here, so nothing extra is collected and no new question is put to you. That table can be sent to people who teach Estonian or study how it is learned, because where a lot of learners go wrong is not something a textbook or a single classroom can measure and this can.",
    "**В чём ошибаются изучающие эстонский, в цифрах.** По тому же журналу повторений эта установка может составить таблицу: как часто правильно отвечают на каждый падеж, каждое изменение основы и каждое слово, в сумме по всем. Она вычисляется из того, что уже есть, поэтому ничего дополнительно не собирается и никаких новых вопросов вам не задаётся. Эту таблицу можно отправить тем, кто преподаёт эстонский или изучает, как его осваивают, потому что где ошибаются многие ученики, не измерит ни учебник, ни отдельный класс, а это может.",
    "**У чому помиляються ті, хто вивчає естонську, у цифрах.** За тим самим журналом повторень ця інсталяція може скласти таблицю: як часто правильно відповідають на кожен відмінок, кожну зміну основи й кожне слово, у сумі за всіма. Вона обчислюється з того, що вже є, тож нічого додатково не збирається і жодних нових запитань вам не ставлять. Цю таблицю можна надіслати тим, хто викладає естонську або вивчає, як її опановують, бо де помиляються багато учнів, не виміряє ні підручник, ні окремий клас, а це може."],
  ["What it holds is counts, and the rules it is built under are the point of it. Nothing is published that fewer than ten different people are behind, or that rests on fewer than fifty answers, and nothing where one person supplied more than half of a figure, because ten people is not ten people when one of them is most of the data. Anything below that is missing from the table rather than shown as a small number. Counts are rounded and people are counted in bands, so two versions of the table cannot be compared to work out what happened in between. There is no user id in it, no email, no date anybody studied, no word anybody searched for and no individual answer. By the time the table exists it is not about you and could not be turned back into anything about you, which is the whole reason it is safe to send.",
    "В ней только подсчёты, и вся суть в правилах, по которым она строится. Не публикуется ничего, за чем стоит меньше десяти разных людей или меньше пятидесяти ответов, и ничего, где больше половины цифры дал один человек, потому что десять человек перестают быть десятью, если один из них дал большую часть данных. Всё, что ниже этого порога, в таблице просто отсутствует, а не показывается маленьким числом. Подсчёты округляются, а люди считаются диапазонами, поэтому две версии таблицы нельзя сравнить, чтобы вычислить, что произошло между ними. В ней нет ни идентификатора пользователя, ни почты, ни дат, когда кто-то занимался, ни слов, которые кто-то искал, ни отдельных ответов. К тому моменту, когда таблица готова, она уже не о вас, и её невозможно превратить обратно во что-либо о вас; именно поэтому её безопасно отправлять.",
    "У ній лише підрахунки, і вся суть у правилах, за якими вона будується. Не публікується нічого, за чим стоїть менше ніж десять різних людей або менше ніж п'ятдесят відповідей, і нічого, де понад половину цифри дала одна людина, бо десять людей перестають бути десятьма, якщо одна з них дала більшу частину даних. Усе, що нижче цього порогу, у таблиці просто відсутнє, а не показується малим числом. Підрахунки округлюються, а людей рахують діапазонами, тож дві версії таблиці не можна порівняти, щоб обчислити, що сталося між ними. У ній немає ні ідентифікатора користувача, ні пошти, ні дат, коли хтось займався, ні слів, які хтось шукав, ні окремих відповідей. На той момент, коли таблиця готова, вона вже не про вас, і її неможливо перетворити назад на будь-що про вас; саме тому її безпечно надсилати."],
  ["You can still say no. {setting} leaves your answers out of it, and out means your rows are skipped when the totals are worked out rather than removed from the answer afterwards. Nothing else about the app changes.",
    "Вы всё равно можете отказаться. {setting} исключает из неё ваши ответы, и «исключает» значит, что ваши строки пропускаются при подсчёте итогов, а не вычитаются из результата потом. Больше в приложении ничего не меняется.",
    "Ви все одно можете відмовитися. {setting} виключає з неї ваші відповіді, і «виключає» означає, що ваші рядки пропускаються під час підрахунку підсумків, а не віднімаються з результату потім. Більше в застосунку нічого не змінюється."],
  ["What is kept on your own device", "Что хранится на вашем устройстве", "Що зберігається на вашому пристрої"],
  ["One cookie keeps you signed in. Beyond that the app stores a few things in the browser itself: whether you chose the dark theme, whether you have already been offered the install prompt, an outbox holding any card you graded while the network was down, so that grade is not lost and is sent with the time you actually answered it, a mock exam paper you have started but not handed in, so that closing the tab three hours into a B2 paper does not throw the whole sitting away, today's word puzzle, so a reload does not lose the guesses you have made, and which card a review round was on, so opening a word's dictionary entry and coming back returns you to it.",
    "Один файл cookie позволяет вам оставаться в аккаунте. Кроме него приложение хранит в самом браузере несколько вещей: выбрали ли вы тёмную тему; предлагали ли вам уже установить приложение; очередь исходящих с карточками, которые вы оценили без сети, чтобы оценка не потерялась и ушла со временем, когда вы на самом деле ответили; начатый, но не сданный пробный экзамен, чтобы закрытая через три часа после начала B2 вкладка не перечеркнула всю попытку; сегодняшнюю словесную головоломку, чтобы после перезагрузки не пропали ваши догадки; и на какой карточке был раунд повторения, чтобы, открыв словарную статью слова и вернувшись, вы оказались там же.",
    "Один файл cookie дає вам змогу лишатися в обліковому записі. Крім нього застосунок зберігає в самому браузері кілька речей: чи вибрали ви темну тему; чи пропонували вам уже встановити застосунок; чергу вихідних з картками, які ви оцінили без мережі, щоб оцінка не загубилася й пішла з часом, коли ви насправді відповіли; розпочатий, але не зданий пробний іспит, щоб закрита через три години після початку B2 вкладка не перекреслила всю спробу; сьогоднішню словесну головоломку, щоб після перезавантаження не зникли ваші здогадки; і на якій картці був раунд повторення, щоб, відкривши словникову статтю слова й повернувшись, ви опинилися там само."],
  ["The unfinished paper holds your answers and when each part's clock runs out. It holds no marks and no questions: the paper is rebuilt from a seed and marked on the server, so nothing kept here can change a score. It is replaced as you write and removed the moment the paper is handed in. The puzzle keeps your guesses and nothing else, and today's word is worked out from the date rather than kept beside them. The card you were on is only its id, gone the moment the round ends or the tab does, whichever comes first.",
    "Незаконченная работа хранит ваши ответы и время, когда истекает каждая её часть. Оценок и вопросов в ней нет: вариант заново собирается из начального числа и проверяется на сервере, поэтому ничто сохранённое здесь не может изменить результат. Она перезаписывается по мере того, как вы пишете, и удаляется в момент сдачи. Головоломка хранит ваши догадки и больше ничего, а сегодняшнее слово вычисляется из даты, а не хранится рядом с ними. От карточки, на которой вы остановились, хранится только её идентификатор, и он исчезает, как только закончится раунд или закроется вкладка, смотря что раньше.",
    "Незакінчена робота зберігає ваші відповіді та час, коли спливає кожна її частина. Оцінок і запитань у ній немає: варіант заново збирається з початкового числа й перевіряється на сервері, тож ніщо збережене тут не може змінити результат. Вона перезаписується в міру того, як ви пишете, і видаляється в момент здачі. Головоломка зберігає ваші здогадки й більше нічого, а сьогоднішнє слово обчислюється з дати, а не зберігається поруч із ними. Від картки, на якій ви зупинилися, зберігається лише її ідентифікатор, і він зникає, щойно закінчиться раунд або закриється вкладка, залежно від того, що станеться раніше."],
  ["None of that is a tracker and none of it is shared with anybody. Estonian law requires your agreement before something is stored on your device unless it is strictly necessary for the service you asked for, and each of these is: a review app that silently drops the answers you gave on a train is broken, not private. That is why there is no cookie banner. Signing out removes the outbox, the saved session, the pages kept for offline use, any unfinished paper and any puzzle, so the next person on a shared computer starts from nothing; the theme and the install prompt stay, since they are about the device rather than about you. The browser also keeps a short code for which account last used it, so that a different account signing in clears the previous one's data even when nobody signed out. Clearing your browser storage removes all of it, and costs you nothing except any grade still waiting to be sent.",
    "Ничто из этого не является трекером, и ничем из этого мы ни с кем не делимся. Эстонский закон требует вашего согласия, прежде чем что-то сохраняется на вашем устройстве, если только это не строго необходимо для услуги, о которой вы попросили, а каждое из перечисленного необходимо: приложение для повторения, которое молча теряет ответы, данные вами в поезде, не бережёт вашу приватность, а просто сломано. Поэтому здесь нет баннера о файлах cookie. Выход из аккаунта удаляет очередь исходящих, сохранённое занятие, страницы для работы без сети, незаконченную работу и головоломку, так что следующий человек за общим компьютером начинает с нуля; тема и предложение установки остаются, потому что они касаются устройства, а не вас. Браузер также хранит короткий код того, какой аккаунт пользовался им последним, чтобы вход другого аккаунта стирал данные предыдущего, даже если никто не вышел. Очистка хранилища браузера удаляет всё это и ничего вам не стоит, кроме оценки, которая ещё ждёт отправки.",
    "Ніщо з цього не є трекером, і нічим із цього ми ні з ким не ділимося. Естонський закон вимагає вашої згоди, перш ніж щось зберігається на вашому пристрої, якщо тільки це не суворо необхідно для послуги, про яку ви попросили, а кожне з переліченого необхідне: застосунок для повторення, який мовчки губить відповіді, дані вами в потязі, не береже вашої приватності, а просто зламаний. Тому тут немає банера про файли cookie. Вихід з облікового запису видаляє чергу вихідних, збережене заняття, сторінки для роботи без мережі, незакінчену роботу й головоломку, тож наступна людина за спільним комп'ютером починає з нуля; тема і пропозиція встановлення лишаються, бо вони стосуються пристрою, а не вас. Браузер також зберігає короткий код того, який обліковий запис користувався ним останнім, щоб вхід іншого облікового запису стирав дані попереднього, навіть якщо ніхто не вийшов. Очищення сховища браузера видаляє все це й нічого вам не коштує, крім оцінки, яка ще чекає на відправлення."],
  ["Who else sees it", "Кто ещё это видит", "Хто ще це бачить"],
  ["This installation only talks to the services below, and nobody else. Each one gets only what’s described beside it, and none of them is paid to profile you.",
    "Эта установка обращается только к сервисам ниже и больше ни к кому. Каждый получает только то, что описано рядом с ним, и никому из них не платят за то, чтобы составлять ваш профиль.",
    "Ця інсталяція звертається лише до сервісів нижче й більше ні до кого. Кожен отримує лише те, що описано поруч із ним, і нікому з них не платять за те, щоб складати ваш профіль."],
  ["In Estonia.", "В Эстонии.", "В Естонії."],
  ["Outside the European Economic Area.", "За пределами Европейской экономической зоны.", "За межами Європейської економічної зони."],
  ["Where this is hosted depends on how the installation was set up, so ask the operator above.",
    "Где это размещено, зависит от того, как настроена установка, поэтому спросите у оператора, указанного выше.",
    "Де це розміщено, залежить від того, як налаштовано інсталяцію, тож запитайте в оператора, вказаного вище."],
  ["Your deck, your review history, your tasks and your level checks are never sent to any of them. The counted table described further up is the one thing that may go to somebody not on this list, and it holds none of those: it is totals, and it is only totals that at least ten people are behind.",
    "Ваша колода, история повторений, задания и проверки уровня никогда не отправляются никому из них. Таблица подсчётов, описанная выше, остаётся единственным, что может уйти кому-то не из этого списка, и в ней нет ничего из перечисленного: это итоги, и только такие, за которыми стоит не меньше десяти человек.",
    "Ваша колода, історія повторень, завдання й перевірки рівня ніколи не надсилаються нікому з них. Таблиця підрахунків, описана вище, лишається єдиним, що може піти комусь не з цього списку, і в ній немає нічого з переліченого: це підсумки, і лише такі, за якими стоїть щонайменше десять людей."],
  ["**Some of that leaves the European Economic Area.** The AI providers are established outside it, so what you type to Anu and any page you photograph crosses a border to be read. That transfer rests on the standard contractual clauses the provider publishes, and nothing else. It is worth knowing that protection there is not identical to protection here. It is also avoidable: the tutor and the page scanner are the only features that do it, and using neither means nothing of yours leaves.",
    "**Часть этого покидает Европейскую экономическую зону.** Поставщики ИИ учреждены за её пределами, поэтому то, что вы пишете Ану, и любая сфотографированная вами страница пересекают границу, чтобы их прочитали. Эта передача основана на стандартных договорных условиях, которые публикует поставщик, и ни на что больше. Стоит знать, что защита там не тождественна защите здесь. Этого можно и избежать: данные передают только репетитор и сканер страниц, и если не пользоваться ни тем, ни другим, ничего вашего не уходит.",
    "**Частина цього залишає Європейську економічну зону.** Постачальники ШІ засновані за її межами, тож те, що ви пишете Ану, і будь-яка сфотографована вами сторінка перетинають кордон, щоб їх прочитали. Ця передача ґрунтується на стандартних договірних умовах, які публікує постачальник, і ні на що більше. Варто знати, що захист там не тотожний захисту тут. Цього можна й уникнути: дані передають лише репетиторка і сканер сторінок, і якщо не користуватися ні нею, ні сканером, нічого вашого не йде."],
  ["None of it is sold, and we never use it to train a model ourselves. What a provider does with what we send them is governed by their own terms. That is a real limit on this promise rather than a formality: some free tiers are free because the provider keeps the right to look at what goes through them.",
    "Ничего из этого не продаётся, и мы сами никогда не обучаем на этом модели. Что поставщик делает с тем, что мы ему отправляем, определяют его собственные условия. Это настоящее ограничение этого обещания, а не формальность: некоторые бесплатные тарифы бесплатны именно потому, что поставщик оставляет за собой право просматривать то, что через них проходит.",
    "Нічого з цього не продається, і ми самі ніколи не навчаємо на цьому моделей. Що постачальник робить із тим, що ми йому надсилаємо, визначають його власні умови. Це справжнє обмеження цієї обіцянки, а не формальність: деякі безплатні тарифи безплатні саме тому, що постачальник залишає за собою право переглядати те, що через них проходить."],
  ["How long it is kept", "Как долго это хранится", "Як довго це зберігається"],
  ["Your learning, your conversations and your scanned word lists are kept for as long as you keep the account, because their whole value is that they are long. The scheduling works off years of history and a level check is only useful next to the one before it.",
    "Ваша учёба, разговоры и отсканированные списки слов хранятся, пока у вас есть аккаунт, потому что вся их ценность в том, что они длинные. Расписание строится на годах истории, а проверка уровня полезна только рядом с предыдущей.",
    "Ваше навчання, розмови й відскановані списки слів зберігаються, доки у вас є обліковий запис, бо вся їхня цінність у тому, що вони довгі. Розклад будується на роках історії, а перевірка рівня корисна лише поруч із попередньою."],
  ["Spending records are kept for the running year, since the caps they enforce are daily. Error logs are short-lived by nature and hold no name. There is no separate archive, and no backup that outlives a deletion by more than the hosting provider’s own retention window.",
    "Записи о расходах хранятся в течение текущего года, поскольку лимиты, которые они обеспечивают, дневные. Журналы ошибок по своей природе недолговечны и имён не содержат. Отдельного архива нет, и нет резервной копии, которая переживала бы удаление дольше, чем собственный срок хранения у хостинг-провайдера.",
    "Записи про витрати зберігаються протягом поточного року, оскільки ліміти, які вони забезпечують, денні. Журнали помилок за своєю природою недовговічні й імен не містять. Окремого архіву немає, і немає резервної копії, яка переживала б видалення довше, ніж власний строк зберігання в хостинг-провайдера."],
  ["What you can demand", "Что вы можете потребовать", "Що ви можете вимагати"],
  ["These are your rights under the GDPR. The two people actually use are buttons, so you don’t even have to ask.",
    "Это ваши права по Общему регламенту по защите данных (GDPR). Для двух из них, которыми люди действительно пользуются, есть кнопки, так что просить даже не нужно.",
    "Це ваші права за Загальним регламентом про захист даних (GDPR). Для двох із них, якими люди справді користуються, є кнопки, тож просити навіть не треба."],
  ["**A copy of everything (access, and portability).** Settings has an **Export** button that gives you the whole thing as a JSON file: every card, review, task, setting, scanned page, level check, mock exam paper with your composition in it, tutor message, suggested fix, starred word, word put aside, badge and class membership. It is a real backup, and the same file restores into a fresh installation. One thing is held back: the spending record described above, since that is this installation’s accounting rather than your work. It is deleted with your account like everything else.",
    "**Копия всего (право доступа и право на переносимость данных).** В настройках есть кнопка **Экспорт**, которая выдаёт всё одним файлом JSON: каждую карточку, повторение, задание, настройку, отсканированную страницу, проверку уровня, пробный экзамен с вашим сочинением, сообщение репетитору, предложенное исправление, отмеченное слово, отложенное слово, значок и членство в группе. Это настоящая резервная копия, и этот же файл восстанавливается в новой установке. Одно не выдаётся: запись о расходах, описанная выше, потому что это учёт этой установки, а не ваша работа. Она удаляется вместе с вашим аккаунтом, как и всё остальное.",
    "**Копія всього (право доступу та право на перенесення даних).** У налаштуваннях є кнопка **Експорт**, яка видає все одним файлом JSON: кожну картку, повторення, завдання, налаштування, відскановану сторінку, перевірку рівня, пробний іспит з вашим твором, повідомлення репетиторці, запропоноване виправлення, позначене слово, відкладене слово, значок і членство в групі. Це справжня резервна копія, і цей самий файл відновлюється в новій інсталяції. Одне не видається: запис про витрати, описаний вище, бо це облік цієї інсталяції, а не ваша робота. Він видаляється разом із вашим обліковим записом, як і все інше."],
  ["**Erasure.** {setting} removes all of that immediately, in one go, along with your sign-in record. The shared dictionary stays, because other learners have cards built on it, but any entry you edited stops being attributed to you. Take an export first: this keeps no copy. If this installation is not set up to delete the sign-in record itself, the button says so plainly rather than pretending, and the address at the top of this page is who to ask.",
    "**Право на удаление.** {setting} сразу и за один раз удаляет всё это вместе с вашей записью для входа. Общий словарь остаётся, потому что на нём построены карточки других учеников, но статьи, которые вы правили, перестают быть подписаны вашим именем. Сначала сделайте экспорт: копия не сохраняется. Если эта установка не настроена удалять запись для входа сама, кнопка прямо об этом скажет, а не будет делать вид, и тогда обращайтесь по адресу в начале этой страницы.",
    "**Право на видалення.** {setting} одразу й за один раз видаляє все це разом із вашим записом для входу. Спільний словник лишається, бо на ньому побудовано картки інших учнів, але статті, які ви редагували, перестають бути підписані вашим ім'ям. Спершу зробіть експорт: копія не зберігається. Якщо ця інсталяція не налаштована видаляти запис для входу сама, кнопка прямо про це скаже, а не вдаватиме, і тоді звертайтеся за адресою на початку цієї сторінки."],
  ["**Correction.** Anything you can see, you can change: your settings, your cards, your tasks, your goal. A dictionary entry can be corrected too, and because the dictionary is shared, that correction is attributed to you until you delete your account. Where you would rather somebody looked at it first, the same entry has a button to suggest the change instead of making it.",
    "**Право на исправление.** Всё, что вы видите, вы можете изменить: настройки, карточки, задания, цель. Словарную статью тоже можно исправить, и поскольку словарь общий, это исправление подписано вашим именем, пока вы не удалите аккаунт. Если вы предпочитаете, чтобы сначала кто-то посмотрел, у той же статьи есть кнопка, чтобы предложить изменение, а не вносить его.",
    "**Право на виправлення.** Усе, що ви бачите, ви можете змінити: налаштування, картки, завдання, мету. Словникову статтю теж можна виправити, і оскільки словник спільний, це виправлення підписане вашим ім'ям, доки ви не видалите обліковий запис. Якщо ви хочете, щоб спершу хтось подивився, у тієї самої статті є кнопка, щоб запропонувати зміну, а не вносити її."],
  ["**Restriction and objection.** You can ask for processing to be paused or object to it, in writing, at the address above. In practice almost everything here exists only to deliver the app to you, so the usual answer to an objection is to stop using the part you object to, and erasure is the stronger and faster version of the same thing. The one objection that is a button rather than a letter is {setting}, which takes your answers out of the counts described above.",
    "**Ограничение обработки и возражение.** Вы можете письменно, по адресу выше, попросить приостановить обработку или возразить против неё. На деле почти всё здесь существует только для того, чтобы приложение работало для вас, поэтому обычный ответ на возражение: перестать пользоваться той частью, против которой вы возражаете, а удаление делает то же самое сильнее и быстрее. Единственное возражение, для которого есть кнопка, а не письмо: {setting}. Оно убирает ваши ответы из описанных выше подсчётов.",
    "**Обмеження обробки й заперечення.** Ви можете письмово, за адресою вище, попросити призупинити обробку або заперечити проти неї. Насправді майже все тут існує лише для того, щоб застосунок працював для вас, тож звичайна відповідь на заперечення: перестати користуватися тією частиною, проти якої ви заперечуєте, а видалення робить те саме сильніше й швидше. Єдине заперечення, для якого є кнопка, а не лист: {setting}. Воно прибирає ваші відповіді з описаних вище підрахунків."],
  ["None of this costs anything, and you don’t need to give a reason. A request made in writing gets an answer within a month.",
    "Всё это ничего не стоит, и объяснять причину не нужно. На письменный запрос вы получите ответ в течение месяца.",
    "Усе це нічого не коштує, і пояснювати причину не потрібно. На письмовий запит ви отримаєте відповідь протягом місяця."],
  ["Nothing here decides anything about you", "Здесь ничто не принимает решений о вас", "Тут ніщо не ухвалює рішень про вас"],
  ["The app estimates a CEFR level from what you answered, and predicts your chance of passing a mock exam. Neither is a decision with any legal or similar effect: they are study advice, checked directly against the dictionary rather than judged by a model, and every figure says how thin the evidence behind it is. No qualification, no admission and no result depends on them. There is no automated decision-making in the sense the law means, and no profiling.",
    "Приложение оценивает ваш уровень по шкале CEFR по вашим ответам и прогнозирует, насколько вероятно, что вы сдадите пробный экзамен. Ни то, ни другое не является решением с юридическими или подобными последствиями: это учебный совет, проверенный напрямую по словарю, а не оценённый моделью, и каждая цифра говорит, насколько скудны данные за ней. От них не зависят ни квалификация, ни зачисление, ни какой-либо результат. Автоматизированного принятия решений в том смысле, в каком его понимает закон, нет, как нет и профилирования.",
    "Застосунок оцінює ваш рівень за шкалою CEFR за вашими відповідями і прогнозує, наскільки ймовірно, що ви складете пробний іспит. Ні те, ні інше не є рішенням з юридичними чи подібними наслідками: це навчальна порада, перевірена безпосередньо за словником, а не оцінена моделлю, і кожна цифра каже, наскільки мізерні дані за нею. Від них не залежать ні кваліфікація, ні зарахування, ні будь-який результат. Автоматизованого ухвалення рішень у тому сенсі, у якому його розуміє закон, немає, як немає й профілювання."],
  ["If you are not satisfied", "Если вас что-то не устраивает", "Якщо вас щось не влаштовує"],
  ["Ask the operator first, at the address at the top of this page. If that gets you nowhere, you have the right to complain to the **{authority}** ({local}), which is the supervisory authority for Estonia: {address}, {phone}, {email}, {web}. If you live elsewhere in the Union you may go to your own country’s authority instead. You can also take it to court.",
    "Сначала обратитесь к оператору по адресу в начале этой страницы. Если это ничего не даст, вы вправе подать жалобу в **{authority}** ({local}), надзорный орган Эстонии: {address}, {phone}, {email}, {web}. Если вы живёте в другой стране Европейского союза, можете вместо этого обратиться в надзорный орган своей страны. Вы также можете обратиться в суд.",
    "Спершу зверніться до оператора за адресою на початку цієї сторінки. Якщо це нічого не дасть, ви маєте право подати скаргу до **{authority}** ({local}), наглядового органу Естонії: {address}, {phone}, {email}, {web}. Якщо ви живете в іншій країні Європейського Союзу, можете натомість звернутися до наглядового органу своєї країни. Ви також можете звернутися до суду."],
  ["Estonian Data Protection Inspectorate", "Инспекция по защите данных Эстонии", "Інспекція із захисту даних Естонії"],
  ["Estonian Data Protection Inspectorate@to", "Инспекцию по защите данных Эстонии", "Інспекції із захисту даних Естонії"],
  ["Children", "Дети", "Діти"],
  ["In Estonia a person can agree to a service like this one for themselves from the age of 13, which is the age the Personal Data Protection Act sets. Below that, a parent has to agree. Kodukeel isn’t aimed at younger children and doesn’t knowingly hold their data. If you think a child under 13 has an account here without a parent’s agreement, write to the address above and it will be deleted.",
    "В Эстонии человек может сам дать согласие на такую услугу с 13 лет: этот возраст устанавливает эстонский Закон о защите персональных данных. Если человек младше, согласие должен дать родитель. Kodukeel не рассчитан на детей младшего возраста и сознательно не хранит их данные. Если вы считаете, что у ребёнка младше 13 лет здесь есть аккаунт без согласия родителя, напишите по адресу выше, и он будет удалён.",
    "В Естонії людина може сама дати згоду на таку послугу з 13 років: цей вік встановлює естонський Закон про захист персональних даних. Якщо людина молодша, згоду має дати один із батьків. Kodukeel не розрахований на дітей молодшого віку і свідомо не зберігає їхніх даних. Якщо ви вважаєте, що в дитини віком до 13 років тут є обліковий запис без згоди батьків, напишіть за адресою вище, і його буде видалено."],
  ["A school running this for a class is the controller of its students’ data and answers for that agreement. What a teacher can see is deliberately narrow: how much work each student did, which grammar the class as a whole is weakest at, and which grammar each student personally is weakest at as a rolled-up percentage. Never an individual’s deck, their searches or a specific answer.",
    "Школа, которая использует это для класса, является контролёром данных своих учеников и отвечает за это согласие. Учитель намеренно видит немного: сколько поработал каждый ученик, в какой грамматике слабее всего класс в целом и в какой лично каждый ученик, в виде сведённого процента. Никогда не чью-то колоду, поиски или конкретный ответ.",
    "Школа, яка використовує це для класу, є контролером даних своїх учнів і відповідає за цю згоду. Учитель навмисно бачить небагато: скільки попрацював кожен учень, у якій граматиці найслабший клас загалом і в якій особисто кожен учень, у вигляді зведеного відсотка. Ніколи не чиюсь колоду, пошуки чи конкретну відповідь."],
  ["An employer sponsoring a workplace group is the controller of that group’s membership in the same way, and sees a narrower set again: effort, and a band for the paper the group is working toward. The difference is a different query rather than a hidden column, so there is no setting that widens it.",
    "Работодатель, спонсирующий рабочую группу, точно так же является контролёром данных о членстве в ней и видит ещё меньше: усилия и ступень готовности к экзамену, к которому идёт группа. Разница заложена в другом запросе к базе, а не в скрытом столбце, поэтому нет настройки, которая бы это расширила.",
    "Роботодавець, який спонсорує робочу групу, так само є контролером даних про членство в ній і бачить ще менше: зусилля та ступінь готовності до іспиту, до якого йде група. Різниця закладена в іншому запиті до бази, а не в прихованому стовпці, тож немає налаштування, яке б це розширило."],
  ["Getting in touch", "Как с нами связаться", "Як з нами зв'язатися"],
  ["Questions about your data go to the operator named at the top. See also the {terms}.",
    "Вопросы о ваших данных направляйте оператору, указанному в начале. См. также {terms}.",
    "Питання про ваші дані надсилайте операторові, вказаному на початку. Див. також {terms}."],
  ["terms", "условия", "умови"],

  // THE RECIPIENTS, AS lib/legal/recipients.ts GENERATES THEM. A product name
  // the list carries alone (Groq, Anthropic) is a name and prints as it is.
  ["what you type to Anu, and any page you photograph", "то, что вы пишете Ану, и любая сфотографированная вами страница", "те, що ви пишете Ану, і будь-яка сфотографована вами сторінка"],
  ["Ekilex, at the Institute of the Estonian Language", "Ekilex в Институте эстонского языка", "Ekilex в Інституті естонської мови"],
  ["a single word you looked up, with no account attached", "одно слово, которое вы искали, без привязки к аккаунту", "одне слово, яке ви шукали, без прив'язки до облікового запису"],
  ["Wikimedia, which runs Wiktionary", "Фонд Викимедиа, который ведёт Викисловарь", "Фонд Вікімедіа, який веде Вікісловник"],
  ["the same single word, asked for its English meaning, with no account attached", "то же слово, с запросом его значения на английском, без привязки к аккаунту", "те саме слово, із запитом його значення англійською, без прив'язки до облікового запису"],
  ["Resend, which sends our emails", "Resend, который отправляет наши письма", "Resend, який надсилає наші листи"],
  ["your email address, and whatever a message to you says about your own course", "ваш адрес электронной почты и то, что в письме сказано о вашем собственном курсе", "ваша адреса електронної пошти і те, що в листі сказано про ваш власний курс"],
  ["TartuNLP, at the University of Tartu", "TartuNLP в Тартуском университете", "TartuNLP у Тартуському університеті"],
  ["a phrase you asked to hear read aloud, with no account attached", "фраза, которую вы попросили прочитать вслух, без привязки к аккаунту", "фраза, яку ви попросили прочитати вголос, без прив'язки до облікового запису"],
  ["The error reporting endpoint at {host}", "Адрес приёма отчётов об ошибках на {host}", "Адреса прийому звітів про помилки на {host}"],
  ["a description of anything that breaks, with your user id and never your email", "описание всего, что ломается, с вашим идентификатором пользователя и никогда с вашей почтой", "опис усього, що ламається, з вашим ідентифікатором користувача й ніколи з вашою поштою"],
  ["your email address and everything in the database, as the host of both", "ваш адрес электронной почты и всё содержимое базы данных, поскольку и то и другое размещено у него", "ваша адреса електронної пошти і весь вміст бази даних, оскільки і те, й інше розміщено в нього"],
  ["Vercel, which runs the servers this app lives on", "Vercel, где работают серверы этого приложения", "Vercel, де працюють сервери цього застосунку"],
  ["every request you make, while it's being answered, and a log of it that includes your IP address", "каждый ваш запрос, пока на него отвечают, и журнал запросов, в котором есть ваш IP-адрес", "кожен ваш запит, поки на нього відповідають, і журнал запитів, у якому є ваша IP-адреса"],

  // TERMS.
  ["Kodukeel is an app for studying Estonian. These terms are short because the deal is simple: use it to learn Estonian, don’t abuse the shared services behind it, and know what it can and can’t promise you.",
    "Kodukeel помогает учить эстонский язык. Эти условия короткие, потому что договорённость простая: пользуйтесь приложением, чтобы учить эстонский, не злоупотребляйте общими сервисами, на которых оно работает, и знайте, что оно может и чего не может вам обещать.",
    "Kodukeel допомагає вчити естонську мову. Ці умови короткі, бо домовленість проста: користуйтеся ним, щоб учити естонську, не зловживайте спільними сервісами, на яких працює застосунок, і знайте, що він може і чого не може вам обіцяти."],
  ["Who provides it", "Кто его предоставляет", "Хто його надає"],
  ["This installation of Kodukeel is provided by **{name}**{registry}{vat}, at {address}. Reach them directly at {email}. Estonian law asks a provider of an online service for exactly that: a name, a place, and a way to get hold of them quickly without going through a form.",
    "Эту установку Kodukeel предоставляет **{name}**{registry}{vat}, адрес: {address}. Связаться напрямую: {email}. Эстонский закон требует от поставщика онлайн-услуги именно этого: имя, адрес и способ быстро с ним связаться, минуя формы.",
    "Цю інсталяцію Kodukeel надає **{name}**{registry}{vat}, адреса: {address}. Зв'язатися напряму: {email}. Естонський закон вимагає від постачальника онлайн-послуги саме цього: ім'я, адреса і спосіб швидко з ним зв'язатися, оминаючи форми."],
  ["**Whoever runs this installation has not filled their name in**, and they’re supposed to. Kodukeel is software anyone can install, so the provider of the service you’re using is whoever runs this copy, a person or a school, not the people who wrote it. Ask whoever gave you the link. If that’s you, setting `OPERATOR_NAME`, `OPERATOR_ADDRESS` and `OPERATOR_EMAIL` puts your details here and on the {privacy}.",
    "**Тот, кто управляет этой установкой, не указал своё имя**, хотя должен был. Kodukeel может установить кто угодно, поэтому поставщиком услуги, которой вы пользуетесь, является тот, кто управляет этой копией, человек или школа, а не те, кто её написал. Спросите того, кто дал вам ссылку. Если это вы, задайте `OPERATOR_NAME`, `OPERATOR_ADDRESS` и `OPERATOR_EMAIL`, и ваши данные появятся здесь и на {privacy}.",
    "**Той, хто керує цією інсталяцією, не вказав свого імені**, хоча мав би. Kodukeel може встановити будь-хто, тож постачальником послуги, якою ви користуєтеся, є той, хто керує цією копією, людина або школа, а не ті, хто її написав. Запитайте того, хто дав вам посилання. Якщо це ви, задайте `OPERATOR_NAME`, `OPERATOR_ADDRESS` і `OPERATOR_EMAIL`, і ваші дані з'являться тут і на {privacy}."],
  ["It’s free and there’s nothing to buy, so the usual consumer purchase rules don’t apply: there’s no right of withdrawal and no payment terms. If an installation ever starts charging, that’s a different arrangement, and these terms don’t cover it. What it costs somebody to run, and who that is, is set out on the {funding}.",
    "Приложение бесплатное, и покупать здесь нечего, поэтому обычные правила о потребительских покупках не применяются: нет ни права на отказ от договора, ни условий оплаты. Если какая-то установка когда-нибудь начнёт брать деньги, это будет другая договорённость, и эти условия на неё не распространяются. Сколько стоит кому-то содержать приложение и кто этот человек, описано на {funding}.",
    "Застосунок безплатний, і купувати тут нічого, тож звичайні правила щодо споживчих покупок не застосовуються: немає ні права на відмову від договору, ні умов оплати. Якщо якась інсталяція колись почне брати гроші, це буде інша домовленість, і ці умови на неї не поширюються. Скільки коштує комусь утримувати застосунок і хто ця людина, описано на {funding}."],
  ["funding page", "странице о финансировании", "сторінці про фінансування"],
  ["What it promises", "Что оно обещает", "Що він обіцяє"],
  ["Every Estonian word form here comes from Ekilex, the dictionary database run by the Institute of the Estonian Language. None of it is made up by AI. Where a form has been worked out by a fixed rule from one the dictionary stores, the screen says so.",
    "Каждая форма эстонского слова здесь взята из Ekilex, словарной базы Института эстонского языка. Ничего из этого не придумано ИИ. Если форма выведена по твёрдому правилу из той, что хранится в словаре, экран об этом говорит.",
    "Кожна форма естонського слова тут узята з Ekilex, словникової бази Інституту естонської мови. Нічого з цього не вигадано ШІ. Якщо форму виведено за твердим правилом із тієї, що зберігається в словнику, екран про це каже."],
  ["**Anu is a machine, and says so on every screen she speaks from.** You are talking to a language model, not a teacher, and the app has to make that impossible to miss, not just true somewhere in the small print. Which model answered is printed under each reply, because a screen naming the wrong one would be worse than naming none.",
    "**Ану не человек, а машина, и она говорит об этом на каждом экране, где появляется.** Вы разговариваете с языковой моделью, а не с учителем, и приложение должно сделать так, чтобы это невозможно было не заметить, а не просто упомянуть где-то мелким шрифтом. Какая модель ответила, написано под каждым ответом, потому что экран, называющий не ту модель, был бы хуже, чем экран, не называющий никакой.",
    "**Ану не людина, а машина, і вона каже про це на кожному екрані, де з'являється.** Ви розмовляєте з мовною моделлю, а не з учителем, і застосунок має зробити так, щоб це неможливо було не помітити, а не просто згадати десь дрібним шрифтом. Яка модель відповіла, написано під кожною відповіддю, бо екран, що називає не ту модель, був би гіршим за екран, що не називає жодної."],
  ["She isn’t the final word on anything. She can explain grammar and suggest an English translation, but she can still get things wrong. Don’t rely on her for an exam answer without checking it yourself.",
    "Её слово ни в чём не последнее. Она может объяснить грамматику и предложить перевод на английский, но всё равно может ошибиться. Не полагайтесь на неё в ответе на экзамене, не проверив его сами.",
    "Її слово ні в чому не останнє. Вона може пояснити граматику й запропонувати переклад англійською, але все одно може помилитися. Не покладайтеся на неї у відповіді на іспиті, не перевіривши її самі."],
  ["The app comes as it is, with no warranty. It’s a learning aid, not a certified language qualification.",
    "Приложение предоставляется «как есть», без гарантий. Это пособие для учёбы, а не сертифицированная языковая квалификация.",
    "Застосунок надається «як є», без гарантій. Це посібник для навчання, а не сертифікована мовна кваліфікація."],
  ["What we ask of you", "Чего мы просим от вас", "Чого ми просимо від вас"],
  ["Use one account, and use it yourself. Please don’t use the tutor for things that have nothing to do with learning Estonian. It runs on a key that costs money every time it’s used, so each account has a daily limit, to stop one person using it all up for everyone else.",
    "Пользуйтесь одним аккаунтом и пользуйтесь им сами. Пожалуйста, не используйте репетитора для того, что не связано с изучением эстонского. Он работает на ключе, каждое использование которого стоит денег, поэтому у каждого аккаунта есть дневной лимит, чтобы один человек не израсходовал всё за всех.",
    "Користуйтеся одним обліковим записом і користуйтеся ним самі. Будь ласка, не використовуйте репетиторку для того, що не пов'язане з вивченням естонської. Він працює на ключі, кожне використання якого коштує грошей, тож у кожного облікового запису є денний ліміт, щоб одна людина не витратила все за всіх."],
  ["Please don’t write scripts that hammer the dictionary, the speech service or the tutor with requests. Ekilex and TartuNLP are free academic services, and this whole project depends on nobody abusing them.",
    "Пожалуйста, не пишите скрипты, которые засыпают запросами словарь, сервис речи или репетитора. Ekilex и TartuNLP являются бесплатными академическими сервисами, и весь этот проект держится на том, что ими никто не злоупотребляет.",
    "Будь ласка, не пишіть скриптів, які засипають запитами словник, сервіс мовлення чи репетиторку. Ekilex і TartuNLP є безплатними академічними сервісами, і весь цей проєкт тримається на тому, що ними ніхто не зловживає."],
  ["Be 13 or older, or have a parent agree first. Estonia sets the age at which somebody can agree to a service like this for themselves at 13, which is the youngest any country in the Union sets it. Nothing here checks, and saying so plainly is more use than a box anyone can check. If you’re a teacher signing up a class, that agreement is the one thing worth getting before you send the link.",
    "Вам должно быть не меньше 13 лет, иначе сначала нужно согласие родителя. Эстония устанавливает возраст, с которого человек может сам дать согласие на такую услугу, в 13 лет, и ни одна страна Европейского союза не устанавливает его ниже. Здесь ничего не проверяется, и сказать об этом прямо полезнее, чем добавить поле для галочки, которую может поставить кто угодно. Если вы учитель и регистрируете класс, это согласие и есть единственное, что стоит получить до того, как отправить ссылку.",
    "Вам має бути щонайменше 13 років, інакше спершу потрібна згода одного з батьків. Естонія встановлює вік, з якого людина може сама дати згоду на таку послугу, у 13 років, і жодна країна Європейського Союзу не встановлює його нижчим. Тут нічого не перевіряється, і сказати про це прямо корисніше, ніж додати поле для позначки, яку може поставити будь-хто. Якщо ви вчитель і реєструєте клас, ця згода і є єдиним, що варто отримати до того, як надіслати посилання."],
  ["What you own", "Что принадлежит вам", "Що належить вам"],
  ["Your deck, your review history, your tasks and your notes are yours. Export them whenever you like from Settings, in a format that restores into any installation. The dictionary joins two sources with different licenses, so it’s worth being exact here. Every Estonian form and every example sentence comes from {ekilex} and is licensed **CC BY 4.0** by the Institute of the Estonian Language. Every English gloss that was not written for this project comes from {wiktionary} and is licensed **CC BY-SA 4.0** by its contributors, which is the stricter of the two: a work built on it has to be shared on the same terms. Both are credited on the sign-in page and in the footer, and keeping them apart is how the dictionary was designed, not an accident.",
    "Ваша колода, история повторений, задания и заметки принадлежат вам. Экспортируйте их когда угодно в настройках, в формате, который восстанавливается в любой установке. Словарь объединяет два источника с разными лицензиями, поэтому здесь стоит быть точными. Каждая эстонская форма и каждый пример предложения взяты из {ekilex} и распространяются Институтом эстонского языка по лицензии **CC BY 4.0**. Каждый английский перевод, написанный не для этого проекта, взят из {wiktionary} и распространяется его авторами по лицензии **CC BY-SA 4.0**, более строгой из двух: работа, созданная на её основе, должна распространяться на тех же условиях. Оба источника указаны на странице входа и внизу сайта, и разделять их было задумано при создании словаря, а не вышло случайно.",
    "Ваша колода, історія повторень, завдання й нотатки належать вам. Експортуйте їх будь-коли в налаштуваннях, у форматі, який відновлюється в будь-якій інсталяції. Словник поєднує два джерела з різними ліцензіями, тож тут варто бути точними. Кожна естонська форма й кожен приклад речення взяті з {ekilex} і поширюються Інститутом естонської мови за ліцензією **CC BY 4.0**. Кожен англійський переклад, написаний не для цього проєкту, узято з {wiktionary}, і він поширюється його авторами за ліцензією **CC BY-SA 4.0**, суворішою з двох: робота, створена на її основі, має поширюватися на тих самих умовах. Обидва джерела вказано на сторінці входу і внизу сайту, і розділяти їх було задумано під час створення словника, а не вийшло випадково."],
  ["English Wiktionary", "английского Викисловаря", "англійського Вікісловника"],
  ["The order the commonest words are listed in comes from {frequency}, a published count over the OpenSubtitles corpus, also licensed **CC BY-SA 4.0**. It decides nothing but an order: every word shown is the dictionary’s own.",
    "Порядок, в котором перечислены самые частые слова, взят из {frequency}, опубликованного подсчёта по корпусу OpenSubtitles, который тоже распространяется по лицензии **CC BY-SA 4.0**. Он определяет только порядок: каждое показанное слово взято из словаря.",
    "Порядок, у якому перелічено найчастіші слова, узято з {frequency}, опублікованого підрахунку за корпусом OpenSubtitles, який теж поширюється за ліцензією **CC BY-SA 4.0**. Він визначає лише порядок: кожне показане слово взято зі словника."],
  ["Whether a spelling is an Estonian word at all, and which word it is a form of, is answered by a forms list built from Ekilex’s own inflection tables, as published in {wordlist} (**CC BY-SA 4.0**), and from {vabamorf}, Filosoft’s open-source morphological tools for Estonian (**LGPL**). That list decides whether a word is accepted and never what a card teaches: no form from it is ever drilled or marked against.",
    "Является ли написание вообще эстонским словом и формой какого слова оно является, решает список форм, собранный из собственных таблиц словоизменения Ekilex в том виде, как они опубликованы в {wordlist} (**CC BY-SA 4.0**), и из {vabamorf}, открытого набора морфологических инструментов Filosoft для эстонского (**LGPL**). Этот список решает, принимается ли слово, и никогда не решает, чему учит карточка: ни одну форму из него никогда не заучивают и не проверяют по ней ответы.",
    "Чи є написання взагалі естонським словом і формою якого слова воно є, вирішує список форм, зібраний із власних таблиць словозміни Ekilex у тому вигляді, як їх опубліковано в {wordlist} (**CC BY-SA 4.0**), і з {vabamorf}, відкритого набору морфологічних інструментів Filosoft для естонської (**LGPL**). Цей список вирішує, чи приймається слово, і ніколи не вирішує, чого вчить картка: жодну форму з нього ніколи не заучують і не перевіряють за нею відповідей."],
  ["Ending it", "Как прекратить", "Як припинити"],
  ["You can stop and delete your data whenever you like. An installation may cut off an account that’s abusing the shared services described above.",
    "Вы можете остановиться и удалить свои данные когда угодно. Установка может отключить аккаунт, который злоупотребляет описанными выше общими сервисами.",
    "Ви можете зупинитися й видалити свої дані будь-коли. Інсталяція може відключити обліковий запис, який зловживає описаними вище спільними сервісами."],
  ["Which law applies", "Какое право применяется", "Яке право застосовується"],
  ["Estonian law governs these terms and anything arising from them, and the Estonian courts are where a dispute ends up. Nothing here takes away a right you have as a consumer where you live: if the law of your own country gives you something these terms do not, that law wins.",
    "Эти условия и всё, что из них вытекает, регулируются правом Эстонии, а спор в итоге решают эстонские суды. Ничто здесь не отнимает у вас прав, которые есть у вас как у потребителя там, где вы живёте: если закон вашей страны даёт вам то, чего не дают эти условия, действует этот закон.",
    "Ці умови й усе, що з них випливає, регулюються правом Естонії, а спір зрештою вирішують естонські суди. Ніщо тут не забирає у вас прав, які ви маєте як споживач там, де живете: якщо закон вашої країни дає вам те, чого не дають ці умови, діє цей закон."],
  ["Changes", "Изменения", "Зміни"],
  ["If these terms change in a way that affects what happens to your data, the {privacy} changes with them and both carry the date of the change.",
    "Если эти условия изменятся так, что это затронет происходящее с вашими данными, вместе с ними изменится и текст на {privacy}, и на обеих страницах будет стоять дата изменения.",
    "Якщо ці умови зміняться так, що це вплине на те, що відбувається з вашими даними, разом із ними зміниться й текст на {privacy}, і на обох сторінках стоятиме дата зміни."],
];

